const table = regionRows.find((r) => r.zone === zone);
const floor = Number(get(table, 'monthly', 0));
if (comparable == null) return false;
if (!(floor > 0)) return false;
if (!(rate >= comparable)) return false;
return rate >= floor;

const day = get(ctx.entry.terms, 'normal_hours_per_day', null);
const week = get(ctx.entry.terms, 'normal_hours_per_week', null);
if (day == null && week == null) return false;
if (day != null && !(Number(day) <= ctx.lookup.part_time_daily_hours)) return false;
if (week != null && !(Number(week) <= ctx.lookup.part_time_weekly_hours)) return false;
return true;

const employer = (ctx.reads.entity_profile_version ?? []).find(
  (v) =>
    v.status === 'SEALED' &&
    v.effective_range.from <= ctx.entry.effective_range.from &&
    (v.effective_range.to == null || v.effective_range.to >= ctx.entry.effective_range.from),
);
const schedule = get(employer, 'payment_schedule', {});
return ctx.lookup.allowed_frequencies.includes(String(get(schedule, 'frequency', '')));

const catalog = ctx.reads.leave_catalog[0];
