const used =
  sum(
    (ctx.reads.leave_catalog_entry ?? [])
      .filter(
        (e) =>
          e.id !== get(ctx.entry, 'id', '') &&
          !e.is_reversal &&
          e.catalog_id === ctx.entry.catalog_id,
      )
      .map((e) => (e.days ?? []).length / 2),
  ) +
  (ctx.entry.days ?? []).length / 2;
if (used <= ctx.lookup.review_after_days) return true;
const contract = ctx.subject.employment;
return get(get(contract, 'employee_extension_data', {}), 'medical_period_review', null) != null;

const catalog = ctx.reads.leave_catalog[0];
if (catalog == null || catalog.code !== 'WORK_INJURY_LEAVE') return true;
const used =
  sum(
    (ctx.reads.leave_catalog_entry ?? [])
      .filter(
        (e) =>
          e.id !== get(ctx.entry, 'id', '') &&
          !e.is_reversal &&
          e.catalog_id === ctx.entry.catalog_id,
      )
      .map((e) => (e.days ?? []).length / 2),
  ) +
  (ctx.entry.days ?? []).length / 2;
if (used <= ctx.lookup.maximum_days) return true;
const contract = ctx.subject.employment;
return get(get(contract, 'employee_extension_data', {}), 'work_injury_leave_extension', null) != null;

condition:
const end = get(ctx.entry.effective_range, 'to', null);
if (end == null) return false;
if (end === '') return false;
return !['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(ctx.entry.engagement);

validate:
const until = get(ctx.entry.employee_extension_data, 'exit_facts.protected_until', null);
if (until == null) return true;
return String(ctx.entry.effective_range.to) >= String(until);

condition:
const dob = get(ctx.entry.payroll, 'date_of_birth', null);
if (dob == null) return false;
if (dob === '') return false;
return !['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(ctx.entry.engagement);

validate:
const dob = get(ctx.entry.payroll, 'date_of_birth', null);
const date = ctx.entry.effective_range.from;
if (dob == null || dob === '' || dob > date) return true;
const female = get(ctx.entry.payroll, 'gender', null) === 'FEMALE';
const category = female
  ? String(get(ctx.entry.employee_extension_data, 'facts.retirement_category', 'FEMALE_50'))
  : 'MALE';
const rows = ctx.lookup.retirement ?? [];
const rule = rows.find((r) => r.category === category) ?? rows.find((r) => r.category === 'MALE');
if (rule == null) return false;
if (dob < rule.cutoff) return calendar_completed_months(dob, date) < rule.base_years * 12;
const steps = Math.trunc(calendar_completed_months(rule.cutoff, month_start(dob)) / rule.birth_months_per_step) + 1;
return calendar_completed_months(dob, date) < rule.base_years * 12 + Math.min(rule.max_deferral_months, steps);

condition:
const terms = get(ctx.subject.employment, 'terms', {});
const standard = ['STANDARD', ''].includes(String(get(terms, 'statutory_work_category', 'STANDARD')));
const engagement = String(get(ctx.subject.employment, 'engagement', ''));
const dayType = String(get(get(ctx.reads.shift_definition[0], 'variant', {}), 'day_type', 'WORK'));
if (!standard) return false;
if (['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement)) return false;
return dayType === 'WORK';

const terms = get(ctx.subject.employment, 'terms', {});
const standard = ['STANDARD', ''].includes(String(get(terms, 'statutory_work_category', 'STANDARD')));
const engagement = String(get(ctx.subject.employment, 'engagement', ''));
const dayType = String(get(get(ctx.reads.shift_definition[0], 'variant', {}), 'day_type', 'WORK'));
if (!standard) return false;
if (['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement)) return false;
return dayType === 'WORK';

validate:
const v = get(ctx.reads.shift_definition[0], 'variant', {});
const clock = (a, b, next) => {
  const [ah, am] = String(a).split(':').map(Number);
  const [bh, bm] = String(b).split(':').map(Number);
  return bh * 60 + bm - (ah * 60 + am) + (next ? 1440 : 0);
};
const span =
  v.start_time != null && v.end_time != null
    ? clock(v.start_time, v.end_time, v.ends_next_day === true)
    : Number(v.untimed_hours ?? 0) * 60;
const unpaid = sum(
  (v.breaks ?? []).filter((b) => b.paid !== true).map((b) => clock(b.start_time, b.end_time, false)),
);
const ordinary = (span - unpaid) / 60;
return (
  ordinary <= ctx.lookup.daily_hours ||
  (get(ctx.entry, 'planned_overtime_intervals', []) ?? []).length > 0
);

condition:
const terms = get(ctx.subject.employment, 'terms', {});
const standard = ['STANDARD', ''].includes(String(get(terms, 'statutory_work_category', 'STANDARD')));
const engagement = String(get(ctx.subject.employment, 'engagement', ''));
return standard && !['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement);

validate:
const rows = (ctx.reads.roster_entry ?? []).filter(
  (r) => r.work_date !== ctx.entry.work_date,
);
const worked = rows
  .filter((r) => Array.isArray(r.actual_worked_intervals) && r.actual_worked_intervals.length > 0)
  .map((r) => r.work_date)
  .concat(
    Array.isArray(get(ctx.entry, 'actual_worked_intervals', [])) && get(ctx.entry, 'actual_worked_intervals', []).length > 0
      ? [ctx.entry.work_date]
      : [],
  )
  .toSorted();
const span = ctx.lookup.weekly_rest_days - 1;
return !worked.some((d, i) => i + span < worked.length && worked[i + span] === add_days(d, span));

condition:
const terms = get(ctx.subject.employment, 'terms', {});
return (
  get(ctx.subject.employment, 'engagement', '') === 'PART_TIME' &&
  terms != null
);

validate:
// 劳动合同法 第六十八条: on average at most 4 hours a worked day and at most 24 hours in a week
const monday = add_days(ctx.entry.work_date, -((weekday(ctx.entry.work_date) + 6) % 7));
const sunday = add_days(monday, 6);
const rows = (ctx.reads.roster_entry ?? [])
  .filter((r) => r.work_date !== ctx.entry.work_date)
  .concat([ctx.entry])
  .filter((r) => r.work_date >= monday && r.work_date <= sunday);
const hoursOf = (r) =>
  interval_minutes(get(r, 'actual_worked_intervals', []).filter((span) => get(span, 'end', null) != null)) / 60;
const worked = rows.filter((r) => hoursOf(r) > 0);
const hours = sum(worked.map(hoursOf));
if (hours > ctx.lookup.part_time_weekly_hours) return false;
return worked.length === 0 || hours / worked.length <= ctx.lookup.part_time_daily_hours;

condition:
const employment = ctx.subject.employment;
const until = String(get(employment.employee_extension_data, 'facts.nursing_protection_until', ''));
return until !== '' && until >= ctx.entry.work_date;

validate:
const zone = String(ctx.lookup.time_zone);
const asOf = ctx.entry.work_date + 'T23:59:59Z';
const planned = get(ctx.entry, 'planned_overtime_intervals', []) ?? [];
const actual = get(ctx.entry, 'actual_worked_intervals', []) ?? [];
const night =
  clock_window_minutes(planned, zone, '22:00', '06:00', asOf) +
  clock_window_minutes(actual, zone, '22:00', '06:00', asOf);
return planned.length === 0 && night === 0;

const employment = ctx.subject.employment;
const dob = get(employment.payroll, 'date_of_birth', null);
if (dob == null || dob === '') return false;
if (age_on(dob, ctx.entry.work_date) >= ctx.lookup.minimum_age_years) return true;
return get(employment.employee_extension_data, 'facts.minor_employment_approved', false) === true;

const from = ctx.entry.terms.probation_period.from;
const prior = (ctx.reads.employee_contract ?? []).filter(
  (c) =>
    c.id !== get(ctx.entry, 'id', '') &&
    c.status === 'SEALED' &&
    get(c.terms, 'probation_period', null) != null,
);
return !prior.some((c) => c.terms.probation_period.from !== from);

const prior = (ctx.reads.employee_contract ?? []).filter(
  (c) => c.id !== get(ctx.entry, 'id', '') && c.status === 'SEALED',
);
const earliest = prior
  .map((c) => c.effective_range.from)
  .concat([ctx.entry.effective_range.from])
  .toSorted()[0];
const service = calendar_completed_months(earliest, ctx.entry.signed_contract_period.from);
const required =
  service >= ctx.lookup.service_months ||
  prior.filter((c) => c.signed_contract_period != null).length >=
    ctx.lookup.prior_fixed_terms;
if (!required) return true;
return (ctx.reads.workplace_case_catalog_entry ?? []).some(
  (c) =>
    c.kind === 'FIXED_TERM_CONTRACT_REQUEST' &&
    get(c, 'employment_id', null) === get(ctx.entry, 'id', '') &&
    c.opened_on <= get(c.inputs, 'signed_on', '') &&
    get(c.inputs, 'contract_start', '') === ctx.entry.signed_contract_period.from &&
    get(c.inputs, 'contract_end', '') === ctx.entry.signed_contract_period.to,
);

const v = get(ctx.entry, 'variant', {});
const clock = (a, b, next) => {
  const [ah, am] = String(a).split(':').map(Number);
  const [bh, bm] = String(b).split(':').map(Number);
  return bh * 60 + bm - (ah * 60 + am) + (next ? 1440 : 0);
};
const span =
  v.start_time != null && v.end_time != null
    ? clock(v.start_time, v.end_time, v.ends_next_day === true)
    : Number(v.untimed_hours ?? 0) * 60;
const unpaid = sum(
  (v.breaks ?? []).filter((b) => b.paid !== true).map((b) => clock(b.start_time, b.end_time, false)),
);
const ordinary = (span - unpaid) / 60;
return ordinary <= ctx.lookup.daily_hours;

const terms = ctx.entry.terms;
return (
  ctx.lookup.work_classifications.includes(
    String(get(terms, 'statutory_work_category', '')),
  ) &&
  ctx.lookup.residency_statuses.includes(String(get(terms, 'residency_status', '')))
);

const terms = ctx.entry.terms;
const rate = get(terms, 'rate', null);
if (rate == null) return false;
if (!(Number(rate.amount) > ctx.lookup.rate_minimum)) return false;
const day = get(terms, 'normal_hours_per_day', null);
if (day != null && !(Number(day) > ctx.lookup.hours_per_day_minimum)) return false;
const week = get(terms, 'normal_hours_per_week', null);
if (week != null && !(Number(week) > ctx.lookup.hours_per_week_minimum)) return false;
const days = get(terms, 'normal_days_per_week', null);
if (days == null) return true;
if (!(Number(days) >= ctx.lookup.days_per_week_minimum)) return false;
return Number(days) <= ctx.lookup.days_per_week_maximum;

const ext = ctx.entry.employee_extension_data ?? {};
const bad = (ctx.lookup.employee_fields ?? []).some((b) => {
  const value = get(ext, b.field, null);
  if (value == null) return false;
  if (b.minimum != null && Number(value) < b.minimum) return true;
  if (b.maximum != null && Number(value) > b.maximum) return true;
  return b.integer === true && Number(value) !== Math.trunc(Number(value));
});
if (bad) return false;
const retirement = get(ext, 'facts.retirement_category', null);
if (retirement != null && !ctx.lookup.retirement_categories.includes(retirement)) return false;
const schemes = get(ext, 'facts.si_exempt_schemes', []);
if (!Array.isArray(schemes)) return true;
return schemes.every((s) => ctx.lookup.si_exempt_schemes.includes(s));

const ext = ctx.entry.entity_extension_data ?? {};
const bad = (ctx.lookup.entity_fields ?? []).some((b) => {
  const value = get(ext, b.field, null);
  if (value == null) return false;
  if (b.minimum != null && Number(value) < b.minimum) return true;
  if (b.maximum != null && Number(value) > b.maximum) return true;
  return b.integer === true && Number(value) !== Math.trunc(Number(value));
});
if (bad) return false;
const zone = get(ext, 'wage_zone', null);
return zone == null || ctx.lookup.wage_zones.includes(zone);

const reference = String(
  get(ctx.entry.inputs, 'reference', get(ctx.entry.inputs, 'offer_reference', '')),
).trim();
if (get(ctx.entry, 'employment_id', null) == null) return false;
if (reference !== '') return true;
return ctx.entry.evidence_file != null;

return (
  String(get(ctx.entry.inputs, 'signed_on', '')) <= String(ctx.entry.opened_on) &&
  ctx.entry.evidence_file != null
);

const start = String(get(ctx.entry.inputs, 'contract_start', ''));
const end = String(get(ctx.entry.inputs, 'contract_end', ''));
if (start === '') return false;
if (!(end >= start)) return false;
return String(ctx.entry.opened_on) <= start;

const offered = String(get(ctx.entry.inputs, 'offered_on', ''));
const refused = String(get(ctx.entry.inputs, 'refused_on', ''));
const opened = String(ctx.entry.opened_on);
if (offered === '') return false;
if (refused === '') return false;
if (offered > refused) return false;
if (refused > opened) return false;
return ctx.entry.closed_on == null || String(ctx.entry.closed_on) >= refused;

// js
const item = first(ctx.reads.leave_catalog);
if (item == null || !ctx.lookup.no_pay.includes(item.code)) return true;
const employer = ctx.subject.employer;
const cutoff = Number(get(employer, 'pay_cutoff_day', 1));
const halves = get(employer, 'payment_schedule.frequency', 'MONTHLY') === 'SEMI_MONTHLY';
const shifted = (month, by) => add_months(month + '-01', by).slice(0, 7);
const periodOf = (date) => {
	const month = date.slice(0, 7);
	const dayOf = Number(date.slice(8, 10));
	const part = dayOf <= 15 ? 1 : 2;
	if (!halves) return cutoff > 1 && dayOf >= cutoff ? shifted(month, 1) : month;
	if (cutoff <= 1) return month + '-' + part;
	return part === 1 ? month + '-2' : shifted(month, 1) + '-1';
};
const dates = ctx.entry.days.map((day) => day.date);
if (get(ctx.entry, 'is_reversal', false) === true && ctx.reads.leave_catalog_entry.some((row) => row.days.some((day) => dates.includes(day.date))))
	throw 'That day has not been paid yet. Delete the entry instead of reversing it.';
const ran = ctx.reads.payroll_run.map((run) => run.period);
const closed = ctx.entry.days.find((day) => ran.includes(periodOf(day.date)));
if (closed != null)
	throw closed.date + ' is in a period that has already run. Date this entry in the next period to run, and that run takes it.';
return true;
